import React, {useEffect, useMemo, useState} from 'react';
import {User} from 'firebase/auth';
import {addDoc, collection, deleteDoc, doc, onSnapshot, query, serverTimestamp, updateDoc, where, runTransaction} from 'firebase/firestore';
import {db} from './lib/firebase';
import {Plus, Trash2, Shuffle, Users, MessageCircle, MapPin, CalendarDays, Building2, Search, Clock, Star, CheckCircle2, Phone, ArrowLeft, ShieldCheck, SlidersHorizontal, ArrowLeftRight, X, Trophy} from 'lucide-react';
import {registerBackHandler} from './lib/backButton';

type Player = {id:string;name:string};
// kind ausente = partido interno (todos los partidos anteriores). En los partidos contra un rival externo
// el grupo usa los campos "white" y el rival solo tiene nombre y goles: black queda vacío.
type Game = {id:string;date:string;white:string[];black:string[];whiteName:string;blackName:string;whiteScore:number;blackScore:number;notes:string;stats?: Record<string,{goals:number;assists:number}>;comments?: {author:string;text:string}[];kind?:'external';tournament?:string};
type Group = {id:string;name:string;ownerId:string;players:Player[];games:Game[];createdAt?:unknown};

// Estadísticas históricas del grupo, calculadas a partir de los partidos guardados (no se almacenan aparte).
export type RankRow = {id:string;name:string;value:number;rank:number};
// Ranking con empates: quienes tienen el mismo valor comparten puesto (1, 1, 3...).
export function rankRows(values:Record<string,number>,names:Map<string,string>):RankRow[]{
 const rows=[...names].map(([id,name])=>({id,name,value:values[id]||0})).filter(r=>r.value>0).sort((a,b)=>b.value-a.value||a.name.localeCompare(b.name,'es'));
 let rank=0;
 return rows.map((r,i)=>{if(i===0||r.value!==rows[i-1].value)rank=i+1;return {...r,rank}});
}
export function groupHistory(players:Player[],games:Game[]){
 const names=new Map(players.map(p=>[p.id,p.name]));
 const goals:Record<string,number>={},assists:Record<string,number>={},played:Record<string,number>={};
 let totalGoals=0;
 for(const g of games){
  const external=g.kind==='external';
  // En un partido externo solo cuentan los integrantes del grupo (white); el rival no suma participantes.
  const roster=new Set(external?(g.white||[]):[...(g.white||[]),...(g.black||[])]);
  // Total de goles del grupo: en un partido interno, todos los goles los hacen integrantes; en uno externo, solo los propios.
  totalGoals+=(Number(g.whiteScore)||0)+(external?0:(Number(g.blackScore)||0));
  for(const pid of roster){
   played[pid]=(played[pid]||0)+1;
   const s=g.stats?.[pid];
   if(s){goals[pid]=(goals[pid]||0)+(Number(s.goals)||0);assists[pid]=(assists[pid]||0)+(Number(s.assists)||0)}
  }
 }
 // Los rankings muestran a los integrantes actuales; los goles de jugadores quitados siguen sumando en los totales.
 return {totalGames:games.length,totalGoals,avg:games.length?totalGoals/games.length:0,goals:rankRows(goals,names),assists:rankRows(assists,names),played:rankRows(played,names)};
}
type Listing = {id:string;ownerId:string;team:string;zone:string;date:string;format:number;style:'Amistoso'|'Competitivo';description:string;status:'open'|'closed';createdAt?:unknown};
const field='w-full bg-[#0D1117] border border-[#30363D] rounded-lg px-3 py-2 text-[#E1E4E8] outline-none focus:border-[#238636] max-md:py-2.5';
const btn='px-4 py-2 bg-[#238636] hover:bg-[#2ea043] rounded-lg font-bold text-white text-sm disabled:opacity-50 max-md:py-3';
const panel='bg-[#161B22] border border-[#30363D] rounded-xl p-5 max-md:p-4';
// Solo en celulares: lleva la vista a un elemento (en escritorio no hace nada).
const isMobile=()=>typeof window!=='undefined'&&window.matchMedia('(max-width: 767px)').matches;
const scrollToId=(elId:string)=>{if(isMobile())setTimeout(()=>document.getElementById(elId)?.scrollIntoView({behavior:'smooth',block:'start'}),50)};
// Fecha y hora actuales en Argentina. Antes se usaba UTC y después de las 21 h se tomaba el día siguiente.
const AR_TZ='America/Argentina/Buenos_Aires';
const nowAR=()=>{const p:Record<string,string>={};for(const x of new Intl.DateTimeFormat('en-CA',{timeZone:AR_TZ,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()))p[x.type]=x.value;return {date:`${p.year}-${p.month}-${p.day}`,time:`${p.hour}:${p.minute}`}};
const today=()=>nowAR().date;
// crypto.randomUUID solo existe en páginas seguras (https o localhost). Si no está (por ejemplo, al abrir
// la versión local desde el celular por la red Wi-Fi), se genera un identificador equivalente.
const id=()=>{if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`};
const clean=(s:string)=>s.trim().slice(0,100);
const errorEnEsp=(e:unknown)=>{const m=String(e);return /permission-denied|insufficient permissions/i.test(m)?'No tenés permisos de Firebase para esta operación. Publicá las reglas del archivo firestore.rules en Firebase Console → Firestore Database → Reglas.':m};

export function Groups({user}:{user:User}){
 const [groups,setGroups]=useState<Group[]>([]),[selected,setSelected]=useState(''),[name,setName]=useState(''),[playerName,setPlayerName]=useState('');
 const [participants,setParticipants]=useState<string[]>([]),[white,setWhite]=useState<string[]>([]),[black,setBlack]=useState<string[]>([]);
 const [whiteName,setWhiteName]=useState('Blanco'),[blackName,setBlackName]=useState('Negro'),[date,setDate]=useState(today());
 const [scores,setScores]=useState({white:0,black:0}),[comment,setComment]=useState(''),[author,setAuthor]=useState('');
 const [error,setError]=useState(''),[busy,setBusy]=useState(false);
 const [openGames,setOpenGames]=useState<string[]>([]);
 const toggleGame=(gid:string)=>setOpenGames(v=>v.includes(gid)?v.filter(x=>x!==gid):[...v,gid]);
 const [confirmDelete,setConfirmDelete]=useState(false);
 const [mode,setMode]=useState<'internal'|'external'>('internal');
 const [opponent,setOpponent]=useState(''),[tournament,setTournament]=useState(''),[extNotes,setExtNotes]=useState('');
 const [extStats,setExtStats]=useState<Record<string,{goals:number;assists:number}>>({});
 useEffect(()=>onSnapshot(query(collection(db,'groups'),where('ownerId','==',user.uid)),s=>setGroups(s.docs.map(d=>({id:d.id,...d.data()} as Group))),e=>setError(errorEnEsp(e))),[user.uid]);
 const group=groups.find(g=>g.id===selected);
 useEffect(()=>{setParticipants([]);setWhite([]);setBlack([]);setConfirmDelete(false);setMode('internal');resetExternal()},[selected]);
 useEffect(()=>{if(!confirmDelete)return;const k=(e:KeyboardEvent)=>{if(e.key==='Escape')setConfirmDelete(false)};window.addEventListener('keydown',k);const stop=registerBackHandler(()=>setConfirmDelete(false));return ()=>{window.removeEventListener('keydown',k);stop()}},[confirmDelete]);
 const history=useMemo(()=>groupHistory(group?.players||[],group?.games||[]),[group]);
 async function save(changes:Partial<Group>){if(!group)return;setBusy(true);setError('');try{await updateDoc(doc(db,'groups',group.id),changes)}catch(e){setError(errorEnEsp(e))}finally{setBusy(false)}}
 async function create(){if(!clean(name))return;setBusy(true);setError('');try{const r=await addDoc(collection(db,'groups'),{name:clean(name),ownerId:user.uid,players:[],games:[],createdAt:serverTimestamp()});setSelected(r.id);setName('')}catch(e){setError(errorEnEsp(e))}finally{setBusy(false)}}
 const display=(pid:string)=>group?.players.find(p=>p.id===pid)?.name||'Jugador eliminado';
 function randomize(){const ids=[...participants].sort(()=>Math.random()-.5);setWhite(ids.slice(0,Math.ceil(ids.length/2)));setBlack(ids.slice(Math.ceil(ids.length/2)))}
 function move(pid:string,side:'white'|'black'){setWhite(v=>side==='white'?[...v.filter(x=>x!==pid),pid]:v.filter(x=>x!==pid));setBlack(v=>side==='black'?[...v.filter(x=>x!==pid),pid]:v.filter(x=>x!==pid))}
 function addGame(){if(!group||!white.length||!black.length)return;const g:Game={id:id(),date,white,black,whiteName:clean(whiteName)||'Blanco',blackName:clean(blackName)||'Negro',whiteScore:scores.white,blackScore:scores.black,notes:'',stats:{},comments:[]};save({games:[g,...(group.games||[])]});setWhite([]);setBlack([]);setParticipants([])}
 function resetExternal(){setOpponent('');setTournament('');setExtNotes('');setExtStats({})}
 const unassigned=participants.filter(p=>!white.includes(p)&&!black.includes(p));
 function unassign(pid:string){setWhite(v=>v.filter(x=>x!==pid));setBlack(v=>v.filter(x=>x!==pid))}
 const extGoals=participants.reduce((n,pid)=>n+(extStats[pid]?.goals||0),0),extAssists=participants.reduce((n,pid)=>n+(extStats[pid]?.assists||0),0);
 const extInvalid=extGoals>scores.white||extAssists>scores.white;
 // Partido contra un equipo que no pertenece al grupo: solo se guardan los integrantes del grupo que jugaron.
 function addExternal(){
  if(!group||!participants.length||!clean(opponent)||extInvalid)return;
  const stats=Object.fromEntries(participants.map(pid=>[pid,{goals:extStats[pid]?.goals||0,assists:extStats[pid]?.assists||0}]));
  const g:Game={id:id(),kind:'external',date,white:[...participants],black:[],whiteName:clean(group.name),blackName:clean(opponent),whiteScore:scores.white,blackScore:scores.black,notes:extNotes.trim().slice(0,1000),tournament:clean(tournament),stats,comments:[]};
  save({games:[g,...(group.games||[])]});setParticipants([]);setWhite([]);setBlack([]);resetExternal();setScores({white:0,black:0});
 }
 function editGame(game:Game,change:Partial<Game>){save({games:group!.games.map(g=>g.id===game.id?{...g,...change}:g)})}
 // El grupo es un único documento (integrantes, partidos, estadísticas y comentarios van adentro),
 // así que borrarlo no deja datos huérfanos. Las estadísticas personales (users/{uid}/matches) no se tocan.
 // Solo el creador ve sus grupos y las reglas de Firestore solo le permiten a él borrarlos.
 // Se ejecuta únicamente desde el botón de confirmación de la ventana de advertencia.
 async function deleteGroup(){
  if(!group||group.ownerId!==user.uid)return;
  setBusy(true);setError('');
  try{await deleteDoc(doc(db,'groups',group.id));setConfirmDelete(false);setSelected('');setOpenGames([])}catch(e){setConfirmDelete(false);setError(errorEnEsp(e))}finally{setBusy(false)}
 }
 return <section className="space-y-6"><div className={panel}><h3 className="font-black uppercase text-xl mb-2">Mis grupos</h3><p className="text-[#8B949E] text-sm mb-4">Guardá jugadores por nombre, sin obligarlos a registrarse.</p><div className="flex gap-2"><input className={field} placeholder="Nombre del grupo (ej. Persas)" value={name} onChange={e=>setName(e.target.value)}/><button className={btn} disabled={busy||!name.trim()} onClick={create}><Plus size={16}/></button></div>{groups.length>0&&<div className="flex flex-wrap gap-2 mt-4">{groups.map(g=><button key={g.id} onClick={()=>{setSelected(g.id);scrollToId('group-detail')}} className={'rounded-lg px-4 py-2 border text-sm max-md:py-2.5 '+(selected===g.id?'bg-[#238636] border-[#238636]':'border-[#30363D] hover:border-[#238636]')}>{g.name}</button>)}</div>}</div>
 {error&&<p role="alert" className="text-[#f85149]">{error}</p>}
 {group&&<><div id="group-detail" className={panel+' max-md:scroll-mt-20'}><div className="flex justify-between items-center gap-3 mb-4"><h3 className="font-black uppercase text-xl max-md:text-lg">{group.name} <span className="text-[#8B949E] text-sm">· {group.players?.length||0} jugadores</span></h3><button title="Eliminar grupo" aria-label="Eliminar grupo" className="text-[#f85149] max-md:hidden" disabled={busy} onClick={()=>setConfirmDelete(true)}><Trash2 size={18}/></button></div>
 <div className="flex gap-2 mb-4"><input className={field} placeholder="Agregar jugador por nombre" value={playerName} onChange={e=>setPlayerName(e.target.value)}/><button disabled={busy||!playerName.trim()} className={btn} onClick={()=>{if(group.players.some(p=>p.name.toLowerCase()===playerName.trim().toLowerCase())){setError('Ese nombre ya está en el grupo');return}save({players:[...(group.players||[]),{id:id(),name:clean(playerName)}]});setPlayerName('')}}><Plus size={17}/></button></div>
 <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-2 max-md:grid-cols-2">{(group.players||[]).map(p=><div className="bg-[#0D1117] rounded-lg px-3 py-2 flex items-center justify-between text-sm max-md:gap-1" key={p.id}><span className="max-md:truncate">{p.name}</span><button title="Quitar jugador" className="text-[#8B949E] hover:text-[#f85149] max-md:p-2 max-md:-m-2" onClick={()=>save({players:group.players.filter(x=>x.id!==p.id)})}><Trash2 size={14}/></button></div>)}</div><button disabled={busy} onClick={()=>setConfirmDelete(true)} className="md:hidden mt-4 w-full flex items-center justify-center gap-2 py-3 rounded-lg border border-[#f85149]/40 text-[#f85149] text-sm font-bold disabled:opacity-50"><Trash2 size={16}/>Eliminar grupo</button></div>
 <GroupStats history={history}/>
 <div className={panel}>
  <div className="flex gap-2 mb-5 max-md:grid max-md:grid-cols-2" role="tablist" aria-label="Tipo de partido">{(['internal','external'] as const).map(m=><button key={m} role="tab" aria-selected={mode===m} onClick={()=>setMode(m)} className={'px-4 py-2 rounded-lg border text-sm font-bold max-md:py-2.5 max-md:px-2 '+(mode===m?'bg-[#238636] border-[#238636] text-white':'border-[#30363D] text-[#8B949E] hover:border-[#238636]')}>{m==='internal'?'Partido interno':'Contra rival externo'}</button>)}</div>
  <h3 className="font-black uppercase text-xl mb-4">{mode==='internal'?'Armar equipos':'Partido contra rival externo'}</h3><p className="text-sm text-[#8B949E] mb-3">{mode==='internal'?'Elegí los jugadores que van a participar hoy.':'Elegí los integrantes del grupo que jugaron el partido.'}</p><div className="flex flex-wrap gap-2 mb-5">{(group.players||[]).map(p=><button key={p.id} onClick={()=>{setParticipants(v=>v.includes(p.id)?v.filter(x=>x!==p.id):[...v,p.id]);setWhite(v=>v.filter(x=>x!==p.id));setBlack(v=>v.filter(x=>x!==p.id))}} className={'px-3 py-2 border rounded-lg text-xs max-md:py-2.5 max-md:text-sm '+(participants.includes(p.id)?'border-[#238636] bg-[#238636]/20':'border-[#30363D]')}>{p.name}</button>)}</div>
  {mode==='internal'?<>
   <div className="flex gap-2 mb-4 max-md:flex-wrap max-md:items-center"><button className={btn} disabled={participants.length<2} onClick={randomize}><Shuffle size={15} className="inline mr-2"/>Aleatorio</button><span className="text-sm text-[#8B949E] self-center">O asigná cada jugador manualmente</span></div>
   {participants.length>0&&<>
    {unassigned.length>0&&<div className="mb-4"><p className="text-xs uppercase text-[#8B949E] mb-2">Sin asignar · {unassigned.length}</p><div className="flex flex-wrap gap-2">{unassigned.map(pid=><div key={pid} className="flex items-center gap-1 bg-[#0D1117] border border-[#30363D] rounded-lg pl-3 pr-1 py-1 text-sm max-md:max-w-full"><span className="truncate mr-1">{display(pid)}</span><button title={'Asignar a '+(clean(whiteName)||'Blanco')} aria-label={'Asignar '+display(pid)+' a Blanco'} onClick={()=>move(pid,'white')} className="px-2.5 py-1 rounded bg-[#E1E4E8] text-[#0D1117] text-xs font-black max-md:py-2">B</button><button title={'Asignar a '+(clean(blackName)||'Negro')} aria-label={'Asignar '+display(pid)+' a Negro'} onClick={()=>move(pid,'black')} className="px-2.5 py-1 rounded bg-black border border-[#484F58] text-white text-xs font-black max-md:py-2">N</button></div>)}</div></div>}
    <div className="grid grid-cols-2 gap-3 mb-4 max-md:gap-2">{(['white','black'] as const).map(side=>{const list=side==='white'?white:black;const other=side==='white'?'black':'white';return <div key={side} className={'rounded-xl border p-3 min-w-0 max-md:p-2.5 '+(side==='white'?'bg-[#E1E4E8]/[0.06] border-[#E1E4E8]/40':'bg-black/50 border-[#484F58]')}>
     <div className="flex items-center justify-between gap-2 mb-2"><span className="flex items-center gap-2 text-xs font-black uppercase tracking-widest"><span className={'w-3 h-3 rounded-full shrink-0 '+(side==='white'?'bg-[#E1E4E8]':'bg-black border border-[#8B949E]')}/>{side==='white'?'Blanco':'Negro'}</span><span className="text-xs text-[#8B949E] shrink-0" aria-label={list.length+' jugadores'}>{list.length}<span className="max-md:hidden"> {list.length===1?'jugador':'jugadores'}</span></span></div>
     <input className={field} aria-label={'Nombre de equipo '+side} value={side==='white'?whiteName:blackName} onChange={e=>side==='white'?setWhiteName(e.target.value):setBlackName(e.target.value)}/>
     <ul className="mt-2">{list.map(pid=><li key={pid} className="flex items-center gap-1 text-sm border-b border-[#30363D]/60 last:border-0"><span className="flex-1 min-w-0 truncate py-2">{display(pid)}</span><button title={'Pasar a '+(other==='white'?clean(whiteName)||'Blanco':clean(blackName)||'Negro')} aria-label={'Pasar '+display(pid)+' al otro equipo'} onClick={()=>move(pid,other)} className="p-1.5 text-[#8B949E] hover:text-[#7ee2a3] shrink-0"><ArrowLeftRight size={14}/></button><button title="Quitar del equipo" aria-label={'Quitar '+display(pid)+' del equipo'} onClick={()=>unassign(pid)} className="p-1.5 text-[#8B949E] hover:text-[#f85149] shrink-0"><X size={14}/></button></li>)}{!list.length&&<li className="text-xs text-[#8B949E] py-2">Sin jugadores</li>}</ul>
    </div>})}</div>
   </>}
   <div className="grid sm:grid-cols-3 gap-3 mb-3 max-md:grid-cols-2"><label className="text-xs max-md:col-span-2">Fecha<input aria-label="Fecha" type="date" className={field} value={date} onChange={e=>setDate(e.target.value)}/></label><label className="text-xs">Goles {whiteName}<input type="number" min="0" className={field} value={scores.white} onChange={e=>setScores({...scores,white:Math.max(0,Number(e.target.value))})}/></label><label className="text-xs">Goles {blackName}<input type="number" min="0" className={field} value={scores.black} onChange={e=>setScores({...scores,black:Math.max(0,Number(e.target.value))})}/></label></div><button className={btn+' max-md:w-full'} disabled={busy||!white.length||!black.length||white.length+black.length!==participants.length} onClick={addGame}>Guardar partido del grupo</button>
  </>:<>
   <div className="grid sm:grid-cols-2 gap-3 mb-3"><label className="text-xs">Equipo rival<input className={field} maxLength={100} placeholder="Nombre del equipo rival" value={opponent} onChange={e=>setOpponent(e.target.value)}/></label><label className="text-xs">Torneo o competición (opcional)<input className={field} maxLength={100} value={tournament} onChange={e=>setTournament(e.target.value)}/></label></div>
   <div className="grid sm:grid-cols-3 gap-3 mb-3 max-md:grid-cols-2"><label className="text-xs max-md:col-span-2">Fecha<input aria-label="Fecha del partido externo" type="date" className={field} value={date} onChange={e=>setDate(e.target.value)}/></label><label className="text-xs">Goles {group.name}<input type="number" min="0" className={field} value={scores.white} onChange={e=>setScores({...scores,white:Math.max(0,Number(e.target.value))})}/></label><label className="text-xs">Goles {clean(opponent)||'rival'}<input type="number" min="0" className={field} value={scores.black} onChange={e=>setScores({...scores,black:Math.max(0,Number(e.target.value))})}/></label></div>
   {participants.length>0&&<><p className="text-xs uppercase text-[#8B949E] mt-4 mb-2">Goles y asistencias por jugador</p><div className="grid md:grid-cols-2 gap-2 mb-3">{participants.map(pid=><div className="flex gap-2 items-center text-xs" key={pid}><span className="flex-1 truncate">{display(pid)}</span>{(['goals','assists'] as const).map(key=><label key={key} className="flex items-center gap-1">{key==='goals'?'G':'A'}<input type="number" min="0" aria-label={key+' de '+display(pid)} className="w-14 bg-[#0D1117] border border-[#30363D] rounded px-1 py-1 max-md:py-2 max-md:text-center" value={extStats[pid]?.[key]||0} onChange={e=>setExtStats(v=>({...v,[pid]:{goals:v[pid]?.goals||0,assists:v[pid]?.assists||0,[key]:Math.max(0,Number(e.target.value)||0)}}))}/></label>)}</div>)}</div>{extInvalid&&<p role="alert" className="text-xs text-[#f85149] mb-3">La suma de goles y la de asistencias de los jugadores no pueden superar los goles de {group.name} ({scores.white}).</p>}</>}
   <label className="text-xs block mb-3">Comentarios u observaciones (opcional)<textarea className={field+' min-h-[72px] resize-y'} maxLength={1000} value={extNotes} onChange={e=>setExtNotes(e.target.value)}/></label>
   <button className={btn+' max-md:w-full'} disabled={busy||!participants.length||!clean(opponent)||extInvalid} onClick={addExternal}>Guardar partido contra rival</button>
  </>}
 </div>
 <div className={panel}><h3 className="font-black uppercase text-xl mb-4">Historial y opiniones</h3><div className="space-y-4">{(group.games||[]).map(game=><article className="bg-[#0D1117] rounded-xl p-4 border border-[#30363D] max-md:p-3" key={game.id}><div className="flex justify-between gap-3 items-center"><div className="max-md:min-w-0"><p className="text-[#8B949E] text-xs">{game.date}{game.kind==='external'&&<> · <span className="text-[#7ee2a3]">Rival externo</span>{game.tournament&&<> · {game.tournament}</>}</>}</p><h4 className="font-bold max-md:text-lg max-md:leading-tight">{game.whiteName} {game.whiteScore} – {game.blackScore} {game.blackName}</h4></div><button title="Eliminar partido" className="text-[#f85149] max-md:p-2 max-md:-m-2 max-md:shrink-0" onClick={()=>save({games:group.games.filter(g=>g.id!==game.id)})}><Trash2 size={16}/></button></div><button onClick={()=>toggleGame(game.id)} className="md:hidden mt-3 w-full flex items-center justify-center gap-2 text-sm text-[#7ee2a3] border border-[#30363D] rounded-lg py-2.5"><MessageCircle size={14}/>{openGames.includes(game.id)?'Ocultar detalle':'Ver detalle'}</button><div className={openGames.includes(game.id)?'':'max-md:hidden'}><p className="text-xs text-[#8B949E] mt-2">{game.kind==='external'?<>Jugaron: {game.white.map(display).join(', ')}</>:<>{game.white.map(display).join(', ')} vs. {game.black.map(display).join(', ')}</>}</p>{game.kind==='external'&&game.notes&&<p className="text-sm mt-2 whitespace-pre-line break-words">{game.notes}</p>}<p className="text-xs uppercase text-[#8B949E] mt-4 mb-2">Goles y asistencias por jugador</p><div className="grid md:grid-cols-2 gap-2">{[...game.white,...game.black].map(pid=><div className="flex gap-2 items-center text-xs" key={pid}><span className="flex-1 truncate">{display(pid)}</span>{(['goals','assists'] as const).map(key=><label key={key} className="flex items-center gap-1">{key==='goals'?'G':'A'}<input type="number" min="0" aria-label={key+' de '+display(pid)} className="w-14 bg-[#161B22] border border-[#30363D] rounded px-1 py-1 max-md:py-2 max-md:text-center" value={game.stats?.[pid]?.[key]||0} onChange={e=>editGame(game,{stats:{...game.stats,[pid]:{goals:game.stats?.[pid]?.goals||0,assists:game.stats?.[pid]?.assists||0,[key]:Math.max(0,Number(e.target.value))}}})}/></label>)}</div>)}</div><h5 className="text-xs uppercase text-[#8B949E] mt-5 mb-2"><MessageCircle size={13} className="inline"/> Comentarios</h5>{(game.comments||[]).map((c,i)=><p key={i} className="text-sm border-l-2 border-[#238636] pl-3 my-2"><b>{c.author}:</b> {c.text}</p>)}<div className="flex flex-wrap gap-2"><input className={field} placeholder="Tu nombre" value={author} onChange={e=>setAuthor(e.target.value)}/><input className={field} placeholder="Opinión sobre el partido..." value={comment} onChange={e=>setComment(e.target.value)}/><button className={btn+' max-md:w-full'} disabled={!author.trim()||!comment.trim()} onClick={()=>{editGame(game,{comments:[...(game.comments||[]),{author:clean(author),text:comment.trim().slice(0,500)}]});setComment('')}}>Comentar</button></div></div></article>)}{!group.games?.length&&<p className="text-[#8B949E] text-sm">Todavía no hay partidos registrados en este grupo.</p>}</div></div>
 {confirmDelete&&<div className="fixed inset-0 z-[100] bg-black/70 flex items-center justify-center p-4" role="dialog" aria-modal="true" aria-labelledby="delete-group-title" onClick={()=>{if(!busy)setConfirmDelete(false)}}><div className="w-full max-w-md bg-[#161B22] border border-[#30363D] rounded-2xl p-6 max-md:p-5" onClick={e=>e.stopPropagation()}><h4 id="delete-group-title" className="font-black text-lg mb-2 flex items-center gap-2 text-[#f85149] break-words"><Trash2 size={18} className="shrink-0"/>Eliminar «{group.name}»</h4><p className="text-sm leading-relaxed">¿Estás seguro de que querés eliminar este grupo? Esta acción es irreversible y se perderá el historial de partidos y las estadísticas compartidas.</p><div className="flex gap-3 mt-6 max-md:flex-col-reverse"><button autoFocus disabled={busy} className="flex-1 px-4 py-2.5 rounded-lg border border-[#30363D] hover:bg-[#21262D] font-bold text-sm disabled:opacity-50 max-md:py-3" onClick={()=>setConfirmDelete(false)}>Cancelar</button><button disabled={busy} className="flex-1 px-4 py-2.5 rounded-lg bg-[#da3633] hover:bg-[#f85149] text-white font-bold text-sm disabled:opacity-50 max-md:py-3" onClick={deleteGroup}>{busy?'Eliminando...':'Eliminar grupo'}</button></div></div></div>}
 </>}
 <p className="text-[#8B949E] text-xs">Versión inicial: los grupos son privados del creador. El acceso compartido con contraseña, roles de administradores y votaciones se implementarán con autenticación segura en una próxima etapa.</p></section>
}

type History = ReturnType<typeof groupHistory>;
const rankingTabs=[{key:'goals',label:'Goles',unit:['gol','goles']},{key:'assists',label:'Asistencias',unit:['asistencia','asistencias']},{key:'played',label:'Partidos',unit:['partido','partidos']}] as const;
function GroupStats({history}:{history:History}){
 const [tab,setTab]=useState<'goals'|'assists'|'played'>('goals');
 if(!history.totalGames)return <div className={panel}><h3 className="font-black uppercase text-xl mb-2 max-md:text-lg">Estadísticas del grupo</h3><p className="text-[#8B949E] text-sm">Las estadísticas aparecerán cuando registres el primer partido.</p></div>;
 const unit=(key:'goals'|'assists'|'played',n:number)=>{const u=rankingTabs.find(t=>t.key===key)!.unit;return `${n} ${n===1?u[0]:u[1]}`};
 const leaders=[{key:'goals',title:'Máximo goleador',icon:Trophy},{key:'assists',title:'Máximo asistidor',icon:Star},{key:'played',title:'Más partidos jugados',icon:CalendarDays}] as const;
 const rows=history[tab];
 return <div className={panel}>
  <h3 className="font-black uppercase text-xl mb-4 max-md:text-lg">Estadísticas del grupo</h3>
  <div className="grid grid-cols-3 gap-3 mb-4 max-md:gap-2">{[['Partidos',String(history.totalGames)],['Goles',String(history.totalGoals)],['Promedio por partido',history.avg.toLocaleString('es-AR',{maximumFractionDigits:2})]].map(([label,value])=><div key={label} className="bg-[#0D1117] border border-[#30363D] rounded-lg p-3 max-md:p-2.5"><p className="text-[10px] uppercase tracking-wider text-[#8B949E] leading-tight">{label}</p><p className="text-2xl font-black mt-1 max-md:text-xl">{value}</p></div>)}</div>
  <div className="grid md:grid-cols-3 gap-3 mb-5 max-md:gap-2">{leaders.map(({key,title,icon:Icon})=>{const top=history[key].filter(r=>r.rank===1);return <div key={key} className="bg-[#0D1117] border border-[#30363D] rounded-lg p-3 flex items-start gap-3 min-w-0"><Icon size={18} className="text-[#7ee2a3] shrink-0 mt-0.5"/><div className="min-w-0"><p className="text-[10px] uppercase tracking-wider text-[#8B949E]">{title}</p>{top.length?<><p className="font-bold break-words">{top.map(r=>r.name).join(' · ')}</p><p className="text-xs text-[#7ee2a3]">{unit(key,top[0].value)}{top.length>1?' · empate':''}</p></>:<p className="text-sm text-[#8B949E]">Sin datos todavía</p>}</div></div>})}</div>
  <div className="flex gap-2 mb-3 max-md:grid max-md:grid-cols-3" role="tablist" aria-label="Rankings">{rankingTabs.map(t=><button key={t.key} role="tab" aria-selected={tab===t.key} onClick={()=>setTab(t.key)} className={'px-3 py-1.5 rounded-lg border text-xs font-bold max-md:py-2.5 max-md:px-1 '+(tab===t.key?'bg-[#238636] border-[#238636] text-white':'border-[#30363D] text-[#8B949E] hover:border-[#238636]')}>{t.label}</button>)}</div>
  {rows.length?<ol className="divide-y divide-[#30363D]/60">{rows.map(r=><li key={r.id} className="flex items-center gap-3 py-2 text-sm"><span className={'w-7 text-center font-black '+(r.rank===1?'text-[#7ee2a3]':'text-[#8B949E]')}>{r.rank}</span><span className="flex-1 min-w-0 truncate">{r.name}</span><span className="font-bold tabular-nums">{r.value}</span></li>)}</ol>:<p className="text-sm text-[#8B949E]">Todavía no hay {tab==='goals'?'goles':tab==='assists'?'asistencias':'partidos'} cargados.</p>}
 </div>;
}

export function TeamMatches({user}:{user:User}){
 const [list,setList]=useState<Listing[]>([]),[team,setTeam]=useState(''),[zone,setZone]=useState(''),[date,setDate]=useState(''),[format,setFormat]=useState(5),[style,setStyle]=useState<'Amistoso'|'Competitivo'>('Amistoso'),[description,setDescription]=useState(''),[error,setError]=useState('');
 const [showPublish,setShowPublish]=useState(false);
 useEffect(()=>onSnapshot(collection(db,'teamListings'),s=>setList(s.docs.map(d=>({id:d.id,...d.data()} as Listing)).sort((a,b)=>a.date.localeCompare(b.date))),e=>setError(errorEnEsp(e))),[]);
 async function publish(){if(!team.trim()||!zone.trim()||!date)return;try{await addDoc(collection(db,'teamListings'),{ownerId:user.uid,team:clean(team),zone:clean(zone),date,format,style,description:description.trim().slice(0,500),status:'open',createdAt:serverTimestamp()});setTeam('');setDescription('');setShowPublish(false)}catch(e){setError(errorEnEsp(e))}}
 return <section className="space-y-6 max-md:space-y-4"><div className={panel}><div className="flex items-center justify-between gap-3"><h3 className="font-black uppercase text-xl mb-2 max-md:text-lg max-md:mb-1">Publicar partido</h3><button onClick={()=>setShowPublish(v=>!v)} className={'md:hidden shrink-0 '+(showPublish?'px-4 py-2.5 border border-[#30363D] rounded-lg text-sm':btn)}>{showPublish?'Ocultar':<><Plus size={15} className="inline mr-1"/>Publicar</>}</button></div><p className="text-sm text-[#8B949E] mb-4 max-md:mb-0">Buscá otro equipo completo para jugar. No se publican cupos individuales.</p><div className={showPublish?'max-md:mt-4':'max-md:hidden'}><div className="grid sm:grid-cols-2 gap-3 mb-3"><input className={field} placeholder="Nombre de tu equipo" value={team} onChange={e=>setTeam(e.target.value)}/><input className={field} placeholder="Zona" value={zone} onChange={e=>setZone(e.target.value)}/><input aria-label="Fecha y hora" type="datetime-local" className={field} value={date} onChange={e=>setDate(e.target.value)}/><select className={field} value={format} onChange={e=>setFormat(Number(e.target.value))}>{[5,6,7,8,11].map(n=><option key={n} value={n}>Fútbol {n}</option>)}</select><select className={field} value={style} onChange={e=>setStyle(e.target.value as 'Amistoso'|'Competitivo')}><option>Amistoso</option><option>Competitivo</option></select><input className={field} placeholder="Detalles adicionales (opcional)" value={description} onChange={e=>setDescription(e.target.value)}/></div><button className={btn+' max-md:w-full'} disabled={!team.trim()||!zone.trim()||!date} onClick={publish}><Plus size={16} className="inline mr-2"/>Publicar</button></div>{error&&<p className="text-[#f85149] mt-2">{error}</p>}</div><div className="grid md:grid-cols-2 gap-4 max-md:gap-3">{list.map(p=><article className={panel} key={p.id}><div className="flex justify-between gap-3"><h3 className="font-black text-lg max-md:min-w-0 max-md:break-words">{p.team}</h3><span className="text-xs border border-[#30363D] rounded-lg px-2 py-1 h-fit max-md:shrink-0">Fútbol {p.format}</span></div><p className="text-[#8B949E] text-sm mt-3"><MapPin size={14} className="inline"/> {p.zone}</p><p className="text-[#8B949E] text-sm"><CalendarDays size={14} className="inline"/> {p.date.replace('T',' ')}</p><p className="text-[#7ee2a3] text-sm mt-2">{p.style} · {p.status==='open'?'Buscando rival':'Cerrado'}</p>{p.description&&<p className="text-sm mt-2">{p.description}</p>}{p.ownerId===user.uid?<div className="flex gap-2 mt-4"><button className={btn} onClick={()=>updateDoc(doc(db,'teamListings',p.id),{status:p.status==='open'?'closed':'open'}).catch(e=>setError(errorEnEsp(e)))}>{p.status==='open'?'Cerrar publicación':'Reabrir'}</button><button title="Eliminar publicación" className="text-[#f85149] max-md:px-3" onClick={()=>deleteDoc(doc(db,'teamListings',p.id)).catch(e=>setError(errorEnEsp(e)))}><Trash2 size={17}/></button></div>:<p className="text-xs text-[#8B949E] mt-3">Solicitud de rival y reserva: pendientes de integrar.</p>}</article>)}{!list.length&&<p className="text-[#8B949E]">Todavía no hay partidos publicados.</p>}</div></section>
}
type Complex = {id:string;name:string;zone:string;address:string;phone:string;ownerId:string;description?:string;createdAt?:unknown};
type Court = {id:string;complexId:string;ownerId:string;name:string;format:string;price:number;active:boolean};
type Booking = {id:string;slotId:string;complexId:string;complexName:string;courtId:string;courtName:string;complexOwnerId:string;userId:string;organizerName:string;organizerPhone:string;participantIds:string[];date:string;startTime:string;endTime:string;format:string;source:'manual'|'online';status:'confirmed'|'cancelled';paymentStatus:'pending'|'paid';courtPrice:number;commissionAmount:number;totalAmount:number;leaderAmount:number;teamSize:number;createdAt?:unknown};
const hours=['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00','19:00','20:00','21:00','22:00','23:00'];
const money=(n:number)=>'$'+n.toLocaleString('es-AR');
const isPastSlot=(day:string,time:string)=>{const n=nowAR();return day===n.date&&time<=n.time};
const slotKey=(courtId:string,date:string,time:string)=>`${courtId}_${date}_${time.replace(':','')}`;

export function Venues({user,mode='both'}:{user:User;mode?:'both'|'player'|'owner'}){
 const [view,setView]=useState<'search'|'owner'>(mode==='owner'?'owner':'search');
 useEffect(()=>{if(mode==='owner')setView('owner');else if(mode==='player')setView('search')},[mode]);
 const [complexes,setComplexes]=useState<Complex[]>([]),[courts,setCourts]=useState<Court[]>([]),[bookings,setBookings]=useState<Booking[]>([]);
 const [selectedComplex,setSelectedComplex]=useState(''),[selectedCourt,setSelectedCourt]=useState('');
 const [date,setDate]=useState(today()),[search,setSearch]=useState(''),[zone,setZone]=useState('Todas');
 const [notice,setNotice]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const [complexForm,setComplexForm]=useState({name:'',zone:'',address:'',phone:'',description:''});
 const [courtForm,setCourtForm]=useState({name:'Cancha 1',format:'Fútbol 5',price:'40000'});
 const [manualForm,setManualForm]=useState({courtId:'',date:today(),time:'18:00',name:'',phone:''});
 const [bookingTeamSize,setBookingTeamSize]=useState(5);
 const [bookingName,setBookingName]=useState(user.displayName||'');
 const [bookingPhone,setBookingPhone]=useState('');
 const [showComplexForm,setShowComplexForm]=useState(false);
 const [showCourtForm,setShowCourtForm]=useState(false);
 const [showManualForm,setShowManualForm]=useState(false);

 useEffect(()=>{
  const stop=onSnapshot(query(collection(db,'complexes')),snap=>setComplexes(snap.docs.map(d=>({id:d.id,...d.data()} as Complex))),e=>setError(errorEnEsp(e)));
  return stop;
 },[]);
 useEffect(()=>{
  const stop=onSnapshot(query(collection(db,'courts')),snap=>setCourts(snap.docs.map(d=>({id:d.id,...d.data()} as Court)).filter(c=>c.active!==false)),e=>setError(errorEnEsp(e)));
  return stop;
 },[]);
 useEffect(()=>{
  const byPlayer=onSnapshot(query(collection(db,'bookings'),where('participantIds','array-contains',user.uid)),snap=>{
   const playerRows=snap.docs.map(d=>({id:d.id,...d.data()} as Booking));
   setBookings(prev=>[...prev.filter(b=>b.complexOwnerId===user.uid),...playerRows].filter(b=>b.status!=='cancelled'));
  },e=>setError(errorEnEsp(e)));
  const byOwner=onSnapshot(query(collection(db,'bookings'),where('complexOwnerId','==',user.uid)),snap=>{
   const ownerRows=snap.docs.map(d=>({id:d.id,...d.data()} as Booking));
   setBookings(prev=>[...prev.filter(b=>b.participantIds?.includes(user.uid)),...ownerRows].filter(b=>b.status!=='cancelled'));
  },e=>setError(errorEnEsp(e)));
  return ()=>{byPlayer();byOwner()};
 },[user.uid]);
 const mine=complexes.filter(c=>c.ownerId===user.uid);
 const current=complexes.find(c=>c.id===selectedComplex)||null;
 const currentCourts=courts.filter(c=>c.complexId===selectedComplex);
 const visible=complexes.filter(c=>(c.name+' '+c.zone+' '+c.address).toLowerCase().includes(search.toLowerCase())&&(zone==='Todas'||c.zone===zone));
  function setMsg(s:string){setNotice(s);setError('')}
 async function createComplex(){if(!complexForm.name.trim()||!complexForm.zone.trim()||!complexForm.address.trim())return;setBusy(true);setError('');try{const ref=await addDoc(collection(db,'complexes'),{...complexForm,name:complexForm.name.trim(),zone:complexForm.zone.trim(),address:complexForm.address.trim(),ownerId:user.uid,createdAt:serverTimestamp()});setSelectedComplex(ref.id);setComplexForm({name:'',zone:'',address:'',phone:'',description:''});setShowComplexForm(false);setMsg('Complejo registrado. Ahora agregá sus canchas y horarios.')}catch(e){setError(errorEnEsp(e))}finally{setBusy(false)}}
 async function createCourt(){if(!selectedComplex||!courtForm.name.trim())return;setBusy(true);try{await addDoc(collection(db,'courts'),{complexId:selectedComplex,ownerId:user.uid,name:courtForm.name.trim(),format:courtForm.format,price:Math.max(0,Number(courtForm.price)||0),active:true,createdAt:serverTimestamp()});setShowCourtForm(false);setMsg('Cancha agregada correctamente.')}catch(e){setError(errorEnEsp(e))}finally{setBusy(false)}}
 async function saveBooking(source:'manual'|'online',court:Court,complex:Complex,day:string,time:string,customerName:string,phone:string){
  const endHour=String((Number(time.slice(0,2))+1)%24).padStart(2,'0')+':'+time.slice(3);
  const idDoc=slotKey(court.id,day,time);
  const participantIds=source==='online'?[user.uid]:[];
  const commissionAmount=source==='online'?bookingTeamSize*2*500:0;
  const totalAmount=court.price+commissionAmount;
  setBusy(true);setError('');
  try{
   // Deterministic slot document prevents two users booking the same court/time concurrently.
   const slotRef=doc(db,'availabilitySlots',idDoc);
   const bookingRef=doc(collection(db,'bookings'));
   await runTransaction(db,async tx=>{
    const slotSnap=await tx.get(slotRef);
    if(slotSnap.exists()&&slotSnap.data().status!=='cancelled')throw new Error('Ese horario acaba de ocuparse. Elegí otro horario.');
    const payload:Omit<Booking,'id'>={slotId:idDoc,complexId:complex.id,complexName:complex.name,courtId:court.id,courtName:court.name,complexOwnerId:complex.ownerId,userId:user.uid,organizerName:customerName.trim(),organizerPhone:phone.trim(),participantIds,date:day,startTime:time,endTime: endHour,format:court.format,source,status:'confirmed',paymentStatus:'pending',courtPrice:court.price,commissionAmount,totalAmount,leaderAmount:Math.ceil(totalAmount/2),teamSize:bookingTeamSize,createdAt:serverTimestamp()};
    tx.set(bookingRef,payload);
    tx.set(slotRef,{complexId:complex.id,courtId:court.id,date:day,startTime:time,endTime:endHour,status:'occupied',source,bookingId:bookingRef.id,complexOwnerId:complex.ownerId,userId:user.uid,updatedAt:serverTimestamp()});
   });
   setMsg(source==='manual'?'Turno externo cargado en la agenda.':'Reserva registrada. El horario ya figura como ocupado y se agregó a tu calendario. El pago queda pendiente de coordinación con el complejo.');
  }catch(e){setError(e instanceof Error?e.message:errorEnEsp(e))}finally{setBusy(false)}
 }
 async function cancelBooking(b:Booking){if(!window.confirm('¿Cancelar este turno? El horario volverá a estar disponible.'))return;setBusy(true);try{await updateDoc(doc(db,'bookings',b.id),{status:'cancelled'});await updateDoc(doc(db,'availabilitySlots',b.slotId||b.id),{status:'cancelled',updatedAt:serverTimestamp()});setMsg('Turno cancelado y horario liberado.')}catch(e){setError(errorEnEsp(e))}finally{setBusy(false)}}
 const [slotMap,setSlotMap]=useState<Record<string,any>>({});
 const [chosenTime,setChosenTime]=useState('');
 useEffect(()=>onSnapshot(query(collection(db,'availabilitySlots'),where('date','==',date)),s=>{const next:Record<string,any>={};s.docs.forEach(d=>next[d.id]=d.data());setSlotMap(next)},e=>setError(errorEnEsp(e))),[date]);
 const [publicComplex,setPublicComplex]=useState('');
 const [publicCourt,setPublicCourt]=useState('');
 const publicSelected=complexes.find(c=>c.id===publicComplex)||null;
 // Botón atrás de Android: desde el detalle de un complejo vuelve al listado (igual que «Volver»).
 useEffect(()=>publicComplex?registerBackHandler(()=>{setPublicComplex('');setChosenTime('')}):undefined,[publicComplex]);
 const publicCourts=courts.filter(c=>c.complexId===publicComplex);
 return <section className="space-y-5">
  <div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-xl uppercase font-black">Canchas y complejos</h3><p className="text-sm text-[#8B949E] mt-1">Una sola agenda para los turnos del complejo y las reservas desde FutData.</p></div>{mode==='both'&&<div className="flex gap-2"><button className={view==='search'?btn:'px-4 py-2 border border-[#30363D] rounded-lg text-sm'} onClick={()=>setView('search')}>Buscar cancha</button><button className={view==='owner'?btn:'px-4 py-2 border border-[#30363D] rounded-lg text-sm'} onClick={()=>setView('owner')}><Building2 size={15} className="inline mr-2"/>Agenda del complejo</button></div>}</div>
  {notice&&<p className="text-sm text-[#7ee2a3] bg-[#238636]/10 rounded-lg p-3">{notice}</p>}{error&&<p role="alert" className="text-sm text-[#f85149] bg-[#f85149]/10 rounded-lg p-3">{error}</p>}
  {view==='search'&&<>
   <div className={panel+(publicSelected?' max-md:hidden':'')}><h4 className="font-bold mb-3"><Search size={16} className="inline mr-2"/>Buscar complejos</h4><div className="grid md:grid-cols-3 gap-3"><input className={field} placeholder="Nombre, localidad o dirección" value={search} onChange={e=>setSearch(e.target.value)}/><select className={field} value={zone} onChange={e=>setZone(e.target.value)}><option>Todas</option>{Array.from(new Set(complexes.map(c=>c.zone))).map(z=><option key={z}>{z}</option>)}</select><input className={field} type="date" value={date} onChange={e=>setDate(e.target.value)}/></div></div>
   {visible.length===0?<div className={panel}><p className="text-sm text-[#8B949E]">{complexes.length?'No se encontraron complejos con esa búsqueda.':<>Todavía no hay complejos publicados.{mode==='both'&&' Podés registrar uno desde «Agenda del complejo».'}</>}</p></div>:<div className={'grid md:grid-cols-2 gap-3'+(publicSelected?' max-md:hidden':'')}>{visible.map(c=><article key={c.id} className={panel}><h4 className="font-black text-lg">{c.name}</h4><p className="text-sm text-[#8B949E] mt-1"><MapPin size={13} className="inline mr-1"/>{c.zone} · {c.address}</p><p className="text-xs text-[#8B949E] mt-2">{c.description||'Complejo deportivo'}</p><button className={btn+' mt-4 max-md:w-full'} onClick={()=>{setPublicComplex(c.id);setPublicCourt(courts.find(x=>x.complexId===c.id)?.id||'');setChosenTime('');if(isMobile())window.scrollTo({top:0})}}>Consultar disponibilidad</button></article>)}</div>}
   {publicSelected&&<div className={panel}><button className="text-sm text-[#7ee2a3] mb-3 max-md:py-2" onClick={()=>{setPublicComplex('');setChosenTime('')}}><ArrowLeft size={14} className="inline mr-1"/>Volver</button><h4 className="font-black text-xl">{publicSelected.name}</h4><p className="text-xs text-[#8B949E] mb-4">Seleccioná cancha y horario. Verde: disponible · Rojo: ocupado.</p><div className="grid md:grid-cols-2 gap-3"><select className={field} value={publicCourt} onChange={e=>{setPublicCourt(e.target.value);setChosenTime('')}}>{publicCourts.map(c=><option key={c.id} value={c.id}>{c.name} · {c.format} · {money(c.price)}</option>)}</select><input className={field} type="date" min={today()} value={date} onChange={e=>{setDate(e.target.value);setChosenTime('')}}/></div>{publicCourts.find(c=>c.id===publicCourt)&&<div className="grid grid-cols-3 sm:grid-cols-4 gap-2 mt-4">{hours.map(t=>{const c=publicCourts.find(x=>x.id===publicCourt)!;const occupied=slotMap[slotKey(c.id,date,t)]?.status==='occupied'||isPastSlot(date,t);return <button key={t} disabled={occupied||busy} onClick={()=>{setSelectedCourt(c.id);setChosenTime(t);scrollToId('booking-form')}} className={'rounded-lg p-3 border text-sm '+(occupied?'bg-red-950/40 border-red-800 text-red-300':'bg-green-950/30 border-green-700 text-green-300 hover:bg-green-900/50')+(chosenTime===t?' max-md:ring-2 max-md:ring-[#7ee2a3]':'')}>{t}<span className="block text-[10px]">{slotMap[slotKey(c.id,date,t)]?.status==='occupied'?'Ocupado':isPastSlot(date,t)?'No disponible':'Disponible'}</span></button>})}</div>}
    {chosenTime&&<div id="booking-form" className="mt-4 bg-[#0D1117] rounded-xl p-4 space-y-3 max-md:scroll-mt-20"><h5 className="font-bold">Solicitar reserva<span className="md:hidden text-[#7ee2a3]"> · {chosenTime}</span></h5><div className="grid md:grid-cols-2 gap-3"><input className={field} placeholder="Nombre del organizador" value={bookingName} onChange={e=>setBookingName(e.target.value)}/><input className={field} placeholder="Teléfono de contacto" value={bookingPhone} onChange={e=>setBookingPhone(e.target.value)}/><select className={field} value={bookingTeamSize} onChange={e=>setBookingTeamSize(Number(e.target.value))}>{[5,6,7,8,11].map(n=><option key={n} value={n}>{n} jugadores por equipo</option>)}</select></div><div className="bg-[#161B22] border border-[#30363D] rounded-lg p-3 text-sm space-y-2"><div className="flex justify-between max-md:gap-3"><span className="text-[#8B949E]">Alquiler de cancha</span><b>{money(publicCourts.find(c=>c.id===publicCourt)?.price||0)}</b></div><div className="flex justify-between max-md:gap-3"><span className="text-[#8B949E]">Servicio FutData ({bookingTeamSize*2} jugadores × $500)</span><b>{money(bookingTeamSize*1000)}</b></div><div className="border-t border-[#30363D] pt-2 flex justify-between font-black"><span>Total</span><span className="text-[#7ee2a3]">{money((publicCourts.find(c=>c.id===publicCourt)?.price||0)+bookingTeamSize*1000)}</span></div><p className="text-xs text-[#8B949E]">Cada líder abonaría {money(Math.ceil(((publicCourts.find(c=>c.id===publicCourt)?.price||0)+bookingTeamSize*1000)/2))}. El pago se coordina con el complejo; todavía no se procesa dentro de FutData.</p></div><button className={btn+' max-md:w-full'} disabled={busy||!bookingName.trim()} onClick={()=>{const c=publicCourts.find(x=>x.id===publicCourt)!;saveBooking('online',c,publicSelected,date,chosenTime,bookingName,bookingPhone);setChosenTime('')}}>Confirmar reserva</button></div>}
   </div>}
  </>}
  {view==='owner'&&<>
   <div className={panel}><div className="flex items-center justify-between gap-3 max-md:flex-col max-md:items-stretch"><div><h4 className="font-black text-lg">Mis complejos</h4><p className="text-xs text-[#8B949E]">Administrá tus canchas y todos los turnos, incluso los que llegan por fuera de FutData.</p></div><button className={btn} onClick={()=>setShowComplexForm(v=>!v)}><Plus size={15} className="inline mr-1"/>Nuevo complejo</button></div>
    {showComplexForm&&<div className="grid md:grid-cols-2 gap-3 mt-4"><input className={field} placeholder="Nombre del complejo" value={complexForm.name} onChange={e=>setComplexForm({...complexForm,name:e.target.value})}/><input className={field} placeholder="Localidad / zona" value={complexForm.zone} onChange={e=>setComplexForm({...complexForm,zone:e.target.value})}/><input className={field} placeholder="Dirección" value={complexForm.address} onChange={e=>setComplexForm({...complexForm,address:e.target.value})}/><input className={field} placeholder="Teléfono" value={complexForm.phone} onChange={e=>setComplexForm({...complexForm,phone:e.target.value})}/><input className={field+' md:col-span-2'} placeholder="Descripción (opcional)" value={complexForm.description} onChange={e=>setComplexForm({...complexForm,description:e.target.value})}/><button className={btn} disabled={busy} onClick={createComplex}>Guardar complejo</button></div>}
    <div className="flex flex-wrap gap-2 mt-4">{mine.map(c=><button key={c.id} className={'px-3 py-2 rounded-lg border text-sm max-md:py-2.5 '+(selectedComplex===c.id?'bg-[#238636] border-[#238636]':'border-[#30363D]')} onClick={()=>setSelectedComplex(c.id)}>{c.name}</button>)}</div>
   </div>
   {current&&<><div className={panel}><div className="flex justify-between items-center gap-2 max-md:flex-col max-md:items-stretch max-md:gap-3"><div><h4 className="font-black text-lg">{current.name} · Agenda</h4><p className="text-xs text-[#8B949E]">Los turnos manuales y online ocupan la misma franja.</p></div><button className={btn} onClick={()=>setShowCourtForm(v=>!v)}><Plus size={15} className="inline mr-1"/>Agregar cancha</button></div>{showCourtForm&&<div className="grid md:grid-cols-3 gap-3 mt-4"><input className={field} placeholder="Nombre (Cancha 1)" value={courtForm.name} onChange={e=>setCourtForm({...courtForm,name:e.target.value})}/><select className={field} value={courtForm.format} onChange={e=>setCourtForm({...courtForm,format:e.target.value})}>{['Fútbol 5','Fútbol 7','Fútbol 8','Fútbol 11','Fútbol sala'].map(x=><option key={x}>{x}</option>)}</select><input className={field} type="number" placeholder="Precio por turno" value={courtForm.price} onChange={e=>setCourtForm({...courtForm,price:e.target.value})}/><button className={btn} onClick={createCourt} disabled={busy}>Guardar cancha</button></div>}
    {currentCourts.length===0&&<p className="text-sm text-[#8B949E] mt-4">Todavía no agregaste canchas a este complejo.</p>}
   </div>
   {currentCourts.length>0&&<div className={panel}><div className="flex flex-wrap justify-between gap-3 items-center mb-4 max-md:flex-col max-md:items-stretch"><div><h4 className="font-black">Agenda diaria</h4><p className="text-xs text-[#8B949E]">Verde: disponible · Rojo: ocupado</p></div><input className={field+' max-w-[180px] max-md:max-w-none'} type="date" value={date} onChange={e=>setDate(e.target.value)}/><button className={btn} onClick={()=>{setManualForm({...manualForm,courtId:currentCourts[0].id,date});setShowManualForm(v=>!v)}}><Plus size={14} className="inline mr-1"/>Cargar turno externo</button></div>
    {showManualForm&&<div className="bg-[#0D1117] rounded-lg p-4 grid md:grid-cols-3 gap-3 mb-4"><select className={field} value={manualForm.courtId} onChange={e=>setManualForm({...manualForm,courtId:e.target.value})}>{currentCourts.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><input className={field} type="date" value={manualForm.date} onChange={e=>setManualForm({...manualForm,date:e.target.value})}/><select className={field} value={manualForm.time} onChange={e=>setManualForm({...manualForm,time:e.target.value})}>{hours.map(h=><option key={h}>{h}</option>)}</select><input className={field} placeholder="Nombre del cliente" value={manualForm.name} onChange={e=>setManualForm({...manualForm,name:e.target.value})}/><input className={field} placeholder="Teléfono (opcional)" value={manualForm.phone} onChange={e=>setManualForm({...manualForm,phone:e.target.value})}/><button className={btn} disabled={busy||!manualForm.name.trim()} onClick={()=>{const c=currentCourts.find(x=>x.id===manualForm.courtId)!;saveBooking('manual',c,current,manualForm.date,manualForm.time,manualForm.name,manualForm.phone);setShowManualForm(false);setDate(manualForm.date)}}>Guardar turno manual</button></div>}
    <div className="space-y-4">{currentCourts.map(c=><div key={c.id} className="border border-[#30363D] rounded-lg p-3 max-md:p-2.5"><div className="flex justify-between mb-3"><div><b>{c.name}</b><p className="text-xs text-[#8B949E]">{c.format} · {money(c.price)}</p></div></div><div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-2">{hours.map(t=>{const occ=slotMap[slotKey(c.id,date,t)];const occupied=occ?.status==='occupied'||isPastSlot(date,t);const booking=bookings.find(b=>b.slotId===slotKey(c.id,date,t));return <div key={t} className={'rounded-lg p-2 border text-center '+(occupied?'bg-red-950/30 border-red-800':'bg-green-950/20 border-green-800')}><b className="text-sm">{t}</b><p className={'text-[10px] '+(occupied?'text-red-300':'text-green-300')}>{slotMap[slotKey(c.id,date,t)]?.status==='occupied'?'Ocupado':isPastSlot(date,t)?'No disponible':'Disponible'}</p>{occ?.status==='occupied'&&<p className="text-[9px] text-[#8B949E] truncate">{occ.source==='manual'?'Manual':'FutData'}</p>}{booking&&<p className="text-[9px] text-[#8B949E] truncate">{booking.organizerName}</p>}</div>})}</div></div>)}</div>
   </div>}
   <div className={panel}><h4 className="font-bold mb-3">Turnos próximos</h4>{bookings.filter(b=>b.complexOwnerId===user.uid&&b.date>=today()).sort((a,b)=>(a.date+a.startTime).localeCompare(b.date+b.startTime)).map(b=><div key={b.id} className="flex flex-wrap justify-between items-center gap-3 border-b border-[#30363D] py-3"><div className="max-md:min-w-0"><b className="text-sm">{b.date} · {b.startTime} · {b.courtName}</b><p className="text-xs text-[#8B949E]">{b.organizerName} · {b.source==='manual'?'Reserva externa':'Reserva por FutData'} · {b.paymentStatus==='pending'?'Pago pendiente':'Pagado'}</p></div><button className="text-xs text-red-300 max-md:text-sm max-md:px-3 max-md:py-2 max-md:border max-md:border-red-800 max-md:rounded-lg" onClick={()=>cancelBooking(b)}>Cancelar</button></div>)}{bookings.filter(b=>b.complexOwnerId===user.uid).length===0&&<p className="text-xs text-[#8B949E]">Los turnos aparecerán acá cuando cargues reservas.</p>}</div></>}
   {!mine.length&&<div className={panel}><p className="text-sm text-[#8B949E]">Todavía no tenés complejos registrados. Creá uno para comenzar a administrar la agenda.</p></div>}
  </>}
  <div className="text-xs text-[#8B949E]">Las reservas realizadas en FutData bloquean el horario en la agenda. Los pagos todavía se coordinan con el complejo y no se procesan dentro de la aplicación.</div>
 </section>
}
